 // Needle sprays: radiating needles with a thin woody midrib.
 ctx.save();ctx.beginPath();ctx.rect(258,2,252,252);ctx.clip();
 for(let b=0;b<9;b++){
  const a=-2.8+b*.7,len=57+biomeHash(b+51)*53,ox=384,oy=134;
  ctx.strokeStyle='#68775b';ctx.lineWidth=1.2;ctx.beginPath();ctx.moveTo(ox,oy);ctx.lineTo(ox+Math.cos(a)*len,oy+Math.sin(a)*len);ctx.stroke();
  for(let n=0;n<25;n++){
   const t=.12+n*.032,x=ox+Math.cos(a)*len*t,y=oy+Math.sin(a)*len*t,h=biomeHash(n+b*27);
   for(const side of [-1,1])leaf(x,y,15+h*14,a+side*.72,1.6+h*2.6,['#acba93','#d0d8ab','#829e79'][n%3]);
  }
 }
 ctx.restore();return atlas;
}
const leafAtlas=makeLeafAtlas();
const leafVertexSource=`attribute vec3 position;attribute vec3 normal;attribute vec2 uv;attribute vec3 tint;
uniform mat4 viewProjection;uniform mat4 lightMatrix;uniform float worldTime;
varying vec2 vUv;varying vec3 vNormal;varying vec3 vTint;varying vec4 vShadow;varying float vFog;
void main(){vec3 p=position;p.x+=sin(position.x*.83+position.z*.43+worldTime*.7)*.035;
 vec4 world=vec4(p,1.);vec4 clip=viewProjection*world;gl_Position=clip;vUv=uv;vNormal=normal;vTint=tint;vShadow=lightMatrix*world;vFog=1.-exp(-max(0.,clip.w-32.)*.006);}`;
const leafFragmentSource=`precision mediump float;uniform sampler2D atlas;uniform sampler2D sunDepth;
uniform vec3 sunDirection;uniform vec3 fogColor;uniform float daylight;uniform float shadowEnabled;uniform float shadowTexel;
varying vec2 vUv;varying vec3 vNormal;varying vec3 vTint;varying vec4 vShadow;varying float vFog;
void main(){vec4 leaf=texture2D(atlas,vUv);if(leaf.a<.45)discard;
 vec3 normal=normalize(vNormal);float light=.47+.53*abs(dot(normal,normalize(sunDirection)));
 vec3 sc=vShadow.xyz/vShadow.w*.5+.5;float visibility=1.;
 if(shadowEnabled>.5&&sc.x>0.&&sc.x<1.&&sc.y>0.&&sc.y<1.&&sc.z>0.&&sc.z<1.){
  visibility=0.;for(int x=0;x<2;x++)for(int y=0;y<2;y++){float depth=texture2D(sunDepth,sc.xy+(vec2(float(x),float(y))-.5)*shadowTexel*1.5).r;visibility+=sc.z-.0018<=depth?.25:0.;}
 }
 vec3 base=pow(clamp(leaf.rgb*vTint*1.37,0.,1.),vec3(2.2));
 vec3 lit=base*(.28+daylight*(.32+light*visibility*.90));lit=lit/(lit+vec3(.58));
 vec3 color=pow(lit,vec3(.454545));gl_FragColor=vec4(mix(color,fogColor,clamp(vFog,0.,.8)),1.);}`;
const leafDepthVertex=`attribute vec3 position;attribute vec2 uv;uniform mat4 matrix;uniform float worldTime;varying vec2 vUv;
void main(){vec3 p=position;p.x+=sin(position.x*.83+position.z*.43+worldTime*.7)*.035;gl_Position=matrix*vec4(p,1.);vUv=uv;}`;
const leafDepthFragment=`precision mediump float;uniform sampler2D atlas;varying vec2 vUv;void main(){if(texture2D(atlas,vUv).a<.45)discard;gl_FragColor=vec4(1.);}`;
if(gpuAvailable){
 const programFor=(vs,fs)=>{const p=gl.createProgram();gl.attachShader(p,shader(gl.VERTEX_SHADER,vs));gl.attachShader(p,shader(gl.FRAGMENT_SHADER,fs));gl.linkProgram(p);if(!gl.getProgramParameter(p,gl.LINK_STATUS))throw Error('Foliage shader: '+gl.getProgramInfoLog(p));return p;};
 leafLayer.program=programFor(leafVertexSource,leafFragmentSource);leafLayer.depthProgram=programFor(leafDepthVertex,leafDepthFragment);leafLayer.buffer=gl.createBuffer();leafLayer.texture=gl.createTexture();
 gl.bindTexture(gl.TEXTURE_2D,leafLayer.texture);gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL,true);gl.texImage2D(gl.TEXTURE_2D,0,gl.RGBA,gl.RGBA,gl.UNSIGNED_BYTE,leafAtlas);gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL,false);
 gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MIN_FILTER,gl.LINEAR_MIPMAP_LINEAR);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MAG_FILTER,gl.LINEAR);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_S,gl.CLAMP_TO_EDGE);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_T,gl.CLAMP_TO_EDGE);gl.generateMipmap(gl.TEXTURE_2D);gl.bindTexture(gl.TEXTURE_2D,null);
}
function leafCard(center,right,up,color,tile){
 const normal=[right[1]*up[2]-right[2]*up[1],right[2]*up[0]-right[0]*up[2],right[0]*up[1]-right[1]*up[0]],length=Math.hypot(...normal)||1;
 for(let k=0;k<3;k++)normal[k]/=length;
 const u0=tile*.5+.006,u1=(tile+1)*.5-.006;
 const corners=[[-1,-1,u0,.012],[1,-1,u1,.012],[1,1,u1,.988],[-1,1,u0,.988]];
 for(const i of [0,1,2,0,2,3]){const [r,u,tx,ty]=corners[i];leafLayer.vertices.push(center[0]+right[0]*r+up[0]*u,center[1]+right[1]*r+up[1]*u,center[2]+right[2]*r+up[2]*u,...normal,tx,ty,...color)}leafLayer.cards++;
}
function leafClump(x,y,z,rx,ry,rz,color,angle,tile){
 // Three intersecting planes, not a screen-facing billboard. The vertical
 // planes carry branch silhouettes; a tilted third plane fills top-down views.
 for(let plane=0;plane<2;plane++){const a=angle+plane*Math.PI*.5;leafCard([x,y,z],[Math.cos(a)*rx*1.45,0,Math.sin(a)*rz*1.45],[0,Math.max(ry,.32)*1.5,0],color,tile)}
 const c=Math.cos(angle),u=Math.sin(angle);leafCard([x,y,z],[c*rx*1.4,.10*ry,u*rz*1.4],[-u*rx*1.4,ry*.35,c*rz*1.4],color,tile);
}
function bindLeafGeometry(p){
 gl.bindBuffer(gl.ARRAY_BUFFER,leafLayer.buffer);
 for(const [name,size,offset] of [['position',3,0],['normal',3,12],['uv',2,24],['tint',3,32]]){const loc=gl.getAttribLocation(p,name);if(loc>=0){gl.enableVertexAttribArray(loc);gl.vertexAttribPointer(loc,size,gl.FLOAT,false,44,offset)}}
}
function uploadFoliage(){if(gpuAvailable){gl.bindBuffer(gl.ARRAY_BUFFER,leafLayer.buffer);gl.bufferData(gl.ARRAY_BUFFER,new Float32Array(leafLayer.vertices),gl.STATIC_DRAW);leafLayer.uploads++;}}
function drawFoliageShadow(){
 if(!gpuAvailable||!leafLayer.cards)return;
 const p=leafLayer.depthProgram;gl.useProgram(p);bindLeafGeometry(p);gl.uniformMatrix4fv(gl.getUniformLocation(p,'matrix'),false,sunMap.matrix);gl.uniform1f(gl.getUniformLocation(p,'worldTime'),state.t);
 gl.activeTexture(gl.TEXTURE1);gl.bindTexture(gl.TEXTURE_2D,leafLayer.texture);gl.uniform1i(gl.getUniformLocation(p,'atlas'),1);gl.drawArrays(gl.TRIANGLES,0,leafLayer.vertices.length/11);leafLayer.depthDraws++;gl.activeTexture(gl.TEXTURE0);
}
function drawFoliage(matrix,atmosphere){
 if(!gpuAvailable||!leafLayer.cards)return;const p=leafLayer.program;gl.useProgram(p);bindLeafGeometry(p);gl.disable(gl.CULL_FACE);
 gl.uniformMatrix4fv(gl.getUniformLocation(p,'viewProjection'),false,matrix);gl.uniformMatrix4fv(gl.getUniformLocation(p,'lightMatrix'),false,sunMap.matrix);gl.uniform1f(gl.getUniformLocation(p,'worldTime'),state.t);
 gl.uniform3f(gl.getUniformLocation(p,'sunDirection'),Math.cos(state.t/24*6.283),.3+atmosphere.daylight*.9,Math.sin(state.t/24*6.283));gl.uniform3f(gl.getUniformLocation(p,'fogColor'),...atmosphere.fog);gl.uniform1f(gl.getUniformLocation(p,'daylight'),atmosphere.daylight);
 gl.activeTexture(gl.TEXTURE0);gl.bindTexture(gl.TEXTURE_2D,sunMap.depth||null);gl.uniform1i(gl.getUniformLocation(p,'sunDepth'),0);gl.uniform1f(gl.getUniformLocation(p,'shadowEnabled'),sunMap.supported?1:0);gl.uniform1f(gl.getUniformLocation(p,'shadowTexel'),sunMap.size?1/sunMap.size:0);
 gl.activeTexture(gl.TEXTURE1);gl.bindTexture(gl.TEXTURE_2D,leafLayer.texture);gl.uniform1i(gl.getUniformLocation(p,'atlas'),1);gl.drawArrays(gl.TRIANGLES,0,leafLayer.vertices.length/11);leafLayer.draws++;
 gl.activeTexture(gl.TEXTURE0);gl.enable(gl.CULL_FACE);gl.useProgram(program);bindGeometry(buffer);
}
function foliageStats(){let invalid=0;const a=leafLayer.vertices;for(let i=0;i<a.length;i++)if(!Number.isFinite(a[i]))invalid++;return {supported:leafLayer.supported,textureWidth:512,textureHeight:256,cards:leafLayer.cards,triangles:leafLayer.vertices.length/33,uploads:leafLayer.uploads,draws:leafLayer.draws,shadowDraws:leafLayer.depthDraws,invalidComponents:invalid,bytes:leafLayer.vertices.length*4,source:'original-procedural-leaf-atlas-v1',alphaTested:true,error:gpuAvailable?gl.getError():null};}

// Crown lobes are original local geometry; no assets or simulation RNG are used.
function foliageLobe(x,y,z,rx,ry,rz,color,angle=0,tile=0){
 if(gpuAvailable){leafClump(x,y,z,rx,ry,rz,color,angle,tile);livingForest.canopyLobes++;return;}
 const start=data.length;ellipsoid(x,y,z,rx,ry,rz,color,6);livingForest.canopyLobes++;
 if(angle){const c=Math.cos(angle),u=Math.sin(angle);for(let i=start;i<data.length;i+=10){const dx=data[i]-x,dz=data[i+2]-z,nx=data[i+3],nz=data[i+5];data[i]=x+c*dx+u*dz;data[i+2]=z-u*dx+c*dz;data[i+3]=c*nx+u*nz;data[i+5]=-u*nx+c*nz;}}
}
function tree(x,z,s=1){
 const start=data.length,y=terrain(x,z),signature=biomeHash(x*1.71+z*3.14),season=climateAt(state.t).season;
 const broadleaf=Math.sin(x*1.71+z*3.14)>.12,bark=rgb(signature>.5?0x6d5742:0x52493a);
 const lean=[.17*Math.sin(x*3.2+z)*s,.13*Math.cos(z*2.7-x)*s],height=(broadleaf?3.5:4.8)*s;
 materialScope(MATERIAL.WOOD,()=>{
  taperedBranch([x,y,z],[x+lean[0],y+height*.86,z+lean[1]],.17*s,.038*s,bark,7);
  for(let root=0;root<4;root++){const a=root*1.57+signature;taperedBranch([x+Math.cos(a)*.36*s,y-.04,z+Math.sin(a)*.36*s],[x,y+.48*s,z],.07*s,.045*s,bark,5);}
 });
 materialScope(MATERIAL.FOLIAGE,()=>{
  if(broadleaf){
   const palette=season===2?[0x7b7435,0xab9349,0x9c6637]:season===3?[0x6a7864,0x85917b,0x74836d]:[0x496a37,0x627b42,0x738c4b];
   for(let branch=0;branch<7;branch++){
    const angle=branch*2.39996+signature*3,reach=(.65+biomeHash(branch+x*.41+z*.27)*.53)*s;
    const tip=[x+lean[0]+Math.cos(angle)*reach,y+(2.04+(branch%3)*.38)*s,z+lean[1]+Math.sin(angle)*reach];
    materialScope(MATERIAL.WOOD,()=>taperedBranch([x,y+1.4*s,z],tip,.07*s,.022*s,bark,5));
    foliageLobe(tip[0],tip[1]+.21*s,tip[2],(.57+.14*(branch%2))*s,.46*s,.63*s,rgb(palette[branch%3]),angle);
    if(branch%2===0)foliageLobe(tip[0]+Math.cos(angle+.6)*.26*s,tip[1]+.51*s,tip[2]+Math.sin(angle+.6)*.26*s,.40*s,.31*s,.46*s,rgb(palette[(branch+1)%3]),angle);
   }
   foliageLobe(x+lean[0],y+3.05*s,z+lean[1],.70*s,.53*s,.68*s,rgb(palette[1]));
  }else{
   const colors=season===3?[0x50665b,0x718577,0x8c9c8b]:[0x365947,0x496b4e,0x637e55];
   for(let tier=0;tier<5;tier++){
    const span=(1.18-tier*.195)*s,base=y+(1.0+tier*.64)*s;
    for(let branch=0;branch<4;branch++){
     const angle=branch*Math.PI*.5+tier*.73+signature*6.28;
     const cx=x+lean[0]*tier/5+Math.cos(angle)*span*.43,cz=z+lean[1]*tier/5+Math.sin(angle)*span*.43;
     materialScope(MATERIAL.WOOD,()=>taperedBranch([x,base+.13*s,z],[x+Math.cos(angle)*span*.96,base-.16*s,z+Math.sin(angle)*span*.96],.034*s,.009*s,bark,4));
     // Elliptical, staggered needle sprays rather than a solid stack of cones.
     foliageLobe(cx,base+.12*s,cz,span*.49,.23*s,span*.79,rgb(colors[(tier+branch)%3]),Math.PI*.5-angle,1);
    }
   }
   foliageLobe(x+lean[0],y+4.32*s,z+lean[1],.21*s,.50*s,.20*s,rgb(colors[2]),0,1);
  }
 });
 livingForest.forestTrees++;livingForest.forestTriangles+=(data.length-start)/30;
}
function fernPatch(x,z,scale,signature){
 const y=terrain(x,z),season=climateAt(state.t).season;
 const leaf=rgb(season===2?0x857044:season===3?0x6d7a5f:0x527447);
 for(let frond=0;frond<6;frond++){
  const angle=frond*1.047+signature*6.28,c=Math.cos(angle),u=Math.sin(angle),length=(.36+.15*biomeHash(signature+frond))*scale;
  for(let j=1;j<5;j++){
   const t=j/5,reach=t*length,yy=y+Math.sin(t*Math.PI*.82)*.27*scale,px=x+c*reach,pz=z+u*reach,spread=(1-t)*.11*scale;
   for(const side of [-1,1]){
    const a=[px-c*.04*scale,yy,pz-u*.04*scale],b=[px-u*spread*side+c*.10*scale,yy+.018*scale,pz+c*spread*side+u*.10*scale],d=[px+c*.06*scale,yy-.018*scale,pz+u*.06*scale];
    tri(a,b,d,leaf);tri(d,b,a,leaf);
   }
  }
 }
 livingForest.understoryPatches++;
}
function woodlandFloor(){
 const begin=data.length;materialScope(MATERIAL.FOLIAGE,()=>{
  for(let index=0;index<trees.length;index++){
   const t=trees[index];if(Math.hypot(t.x-SCENIC_SITES.sanctuary.x,t.z-SCENIC_SITES.sanctuary.z)<8)continue;
   for(let patch=0;patch<2;patch++){
    const h=biomeHash(index*19+patch*7),angle=h*6.28,x=t.x+Math.cos(angle)*(1.0+h)*t.s,z=t.z+Math.sin(angle)*(1.0+h)*t.s;
    if(Math.abs(x)>40||Math.abs(z)>40||!walkable(x,z)||Math.abs(z-20-Math.sin(x*.13)*3)<3)continue;
    fernPatch(x,z,.72+h*.48,h);
   }
  }
 });livingForest.forestTriangles+=(data.length-begin)/30;
